 77:         var machine = MachinePath();
 78:         if (!string.IsNullOrWhiteSpace(machine) &&
 79:             !string.Equals(Path.GetFullPath(path), Path.GetFullPath(machine), StringComparison.OrdinalIgnoreCase))
 80:         {
